<template><ElConfigProvider namespace="kel"><section class="native-query-view"><header><div><h2>{{title}}</h2><small>{{subtitle}}</small></div><KsButton size="small" :loading="loading" @click="emit('refresh')">刷新</KsButton></header><div v-if="kind==='logs'" class="query-controls"><KsInput :modelValue="query.q||''" placeholder="搜索已采集日志" @update:modelValue="v=>emit('filter','q',v)" clearable/><select :value="query.level||''" @change="emit('filter','level',($event.target as HTMLSelectElement).value)"><option value="">所有等级</option><option>ERROR</option><option>WARN</option><option>INFO</option><option>DEBUG</option><option>TRACE</option></select><input type="datetime-local" aria-label="起始时间" :value="query.since?.slice(0,16)" @change="emit('filter','since',($event.target as HTMLInputElement).value)"/><input type="datetime-local" aria-label="结束时间" :value="query.until?.slice(0,16)" @change="emit('filter','until',($event.target as HTMLInputElement).value)"/></div><div v-if="error" class="error" role="alert">{{error}}</div>
<template v-if="kind==='logs'"><div class="native-query-logs"><div v-for="line in data.items||[]" :key="line.id" class="native-query-log"><span>{{new Date(line.timestamp).toLocaleString()}}</span><b :class="line.level.toLowerCase()">{{line.level}}</b><div><button @click="emit('navigate','/flows/executions/'+line.execution_id+'?tab=Logs'+(line.task_run_id?'&task_run='+encodeURIComponent(line.task_run_id):''))">{{line.execution_id.slice(0,12)}} / {{line.task_id||'execution'}} →</button><pre>{{line.message}}</pre></div></div><div v-if="!loading&&!data.items?.length" class="empty">没有匹配的已采集日志</div></div><footer><small>{{data.coverage}}</small><KsButton v-if="data.next_cursor" size="small" @click="emit('more')">加载更早日志</KsButton><KsButton v-if="data.items?.length" size="small" @click="download">导出当前结果</KsButton></footer></template>
<template v-else><div class="summary"><strong>{{data.total??'—'}}</strong><div><b>Execution</b><small>{{data.state_source||'尚无聚合结果'}}</small></div></div><div class="summary-columns"><section><h3>引擎状态</h3><button v-for="(count,state) in data.states||{}" :key="state" class="summary-state" @click="emit('state',String(state))"><span>{{state}}</span><i :style="{width:Math.max(0,Number(count)/Math.max(1,data.total)*100)+'%'}"/><b>{{count}}</b></button><p v-if="!Object.keys(data.states||{}).length" class="empty">没有执行记录</p></section><section><h3>设备结果</h3><div v-for="(count,state) in data.targets||{}" :key="state" class="summary-state"><span>{{state}}</span><b>{{count}}</b></div><p v-if="!Object.keys(data.targets||{}).length" class="empty">没有设备目标记录</p></section></div><template v-if="kind==='concurrency'"><div class="limits"><div><small>Flow 并发限制</small><b>{{limit??'未指定'}}</b></div><div><small>运行中</small><b>{{data.states?.RUNNING||0}}</b></div><div><small>队列</small><b>{{data.states?.QUEUED||0}}</b></div></div><p class="note">限制来自 Flow 定义；排队原因未由引擎报告时不推断。修改限制进入编辑器，保存新 Revision 后生效。</p><KsButton @click="emit('edit')">编辑并发限制</KsButton></template></template>
</section></ElConfigProvider></template>
<script setup lang="ts">
import {ElConfigProvider} from 'element-plus';import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';import KsInput from '../../vendor/kestra/design-system/components/Form/KsInput.vue';
const props=defineProps<{kind:string;title:string;subtitle:string;loading:boolean;error:string;data:any;query:Record<string,string>;limit?:number}>(),emit=defineEmits(['refresh','filter','navigate','more','state','edit']);
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(props.data.items,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='authorized-log-search.json';a.click();URL.revokeObjectURL(url)}
</script>
<style scoped>.native-query-view{color:var(--ks-text-primary);background:var(--ks-bg-surface);font:12px var(--ks-font-family-sans);padding:18px 20px;min-height:460px}header{display:flex;justify-content:space-between;align-items:center;padding-bottom:18px}h2{font-size:18px;margin:0 0 5px}small{font-size:10px;color:var(--ks-text-secondary)}.query-controls{display:flex;gap:8px;flex-wrap:wrap;padding:12px 0;border-block:1px solid var(--ks-border-default)}.query-controls>.kel-input{max-width:350px}.query-controls select,.query-controls input{background:var(--ks-bg-input);border:1px solid var(--ks-border-default);border-radius:4px;padding:6px;color:inherit;font-size:11px}.native-query-logs{max-height:550px;overflow:auto}.native-query-log{display:grid;grid-template-columns:160px 55px 1fr;gap:15px;border-bottom:1px solid var(--ks-border-default);padding:12px 0;font-size:11px}.native-query-log>span{color:var(--ks-text-secondary);font-size:10px}.native-query-log button{color:var(--ks-text-link);font-size:10px}.native-query-log pre{margin:8px 0 0;white-space:pre-wrap;font:11px/1.7 monospace}.native-query-log .error,.error{color:#df7490}.summary{display:flex;align-items:center;gap:16px;padding:25px 0;border-bottom:1px solid var(--ks-border-default)}.summary>strong{font-size:40px;font-weight:500}.summary small{display:block;margin-top:5px}.summary-columns{display:grid;grid-template-columns:1fr 1fr;gap:40px;padding:20px 0}.summary-columns h3{font-size:11px;text-transform:uppercase;color:var(--ks-text-secondary)}.summary-state{display:flex;width:100%;align-items:center;gap:15px;position:relative;min-height:35px;border-bottom:1px solid var(--ks-border-default);font-size:11px;text-align:left}.summary-state>span{min-width:120px}.summary-state>b{margin-left:auto}.summary-state>i{height:4px;max-width:50%;background:var(--ks-text-link);border-radius:2px}.limits{display:grid;grid-template-columns:repeat(3,1fr);padding:18px 0;border-top:1px solid var(--ks-border-default)}.limits b{display:block;font-size:24px;margin-top:6px;font-weight:500}.note,.empty{color:var(--ks-text-secondary);font-size:11px;line-height:1.7}.empty{padding:40px 0}footer{display:flex;align-items:center;gap:10px;padding-top:15px}footer small{margin-right:auto;max-width:65%;line-height:1.6}</style>
